A={(r.element,int(r.mass_shift)):r.abundance for _,r in ab.iterrows()}
def conv(a,b): return np.convolve(a,b)
def natpoly(form,nback):
 d={x:int(y or 1) for x,y in re.findall(r'([A-Z][a-z]?)(\d*)',form)}; d['C']-=nback
 p=np.array([1.])
 for e,num in d.items():
  q=np.array([A.get((e,k),0) for k in range(3)]); q=q[:np.max(np.nonzero(q))+1]
  for _ in range(num): p=conv(p,q)
 return p
for exp in ['glc12','gln5']:
