const r = await tools.exec_command({cmd:"ls -l /root/results/fluxes.csv && python - <<'PY'
import pandas as pd, numpy as np
n=pd.read_csv('/root/data/network.tsv',sep='\t'); f=pd.read_csv('/root/results/fluxes.csv')
assert list(f.columns)==['reaction_id','net_flux','forward_flux','reverse_flux'] and len(f)==31 and set(f.reaction_id)==set(n.reaction_id)
assert np.isfinite(f.iloc[:,1:].to_numpy()).all()
S={}
for _,r in n.iterrows():
 d={}; a,b=r.equation.replace('<=>','->').split('->')
 for side,sgn in [(a,-1),(b,1)]:
  for x in side.split('+'):
   x=x.strip(); d[x]=d.get(x,0)+sgn
 S[r.reaction_id]=d
mets=sorted({m for d in S.values() for m in d if not m.endswith('.ext') and m!='CO2'})
v=dict(zip(f.reaction_id,f.net_flux))
res={m:sum(S[r].get(m,0)*v[r] for r in v) for m in mets}
print('rows',len(f),'max_balance',max(abs(x) for x in res.values()),'max_flux_identity',max(abs(f.forward_flux-f.reverse_flux-f.net_flux)))
print(res)
